 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                # Zero can be foreground too; handled below by checking seen only.
                pass
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = [(r, c)]
            seen.add((r, c))
            cells = set()
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append((color, cells))
    return comps


def _norm(cells):
    my = min(y for y, x in cells)
    mx = min(x for y, x in cells)
    return frozenset((y - my, x - mx) for y, x in cells)


def _bounds(cells):
    return min(y for y, x in cells), max(y for y, x in cells), min(x for y, x in cells), max(x for y, x in cells)


def _find_divider(grid, comps):
    # A divider is a single-color connected component that is exactly an L,
    # with two substantial perpendicular arms meeting at an endpoint.
    choices = []
    for color, cells in comps:
        if len(cells) < 6:
            continue
        ys = [y for y, x in cells]
        xs = [x for y, x in cells]
        for py, px in cells:
            for sy, sx in ((-1, 0), (1, 0)):
                for ty, tx in ((0, -1), (0, 1)):
                    a = 1
                    while (py + sy * a, px + sx * a) in cells:
                        a += 1
                    b = 1
                    while (py + ty * b, px + tx * b) in cells:
                        b += 1
                    if a < 3 or b < 3:
                        continue
                    shape = {(py + sy * k, px + sx * k) for k in range(a)} | {(py + ty * k, px + tx * k) for k in range(b)}
                    if shape == cells:
                        choices.append((a + b, color, cells, py, px, sy, sx, ty, tx))
    if not choices:
        return None
    choices.sort(key=lambda z: (z[0], len(z[2])), reverse=True)
    _, color, cells, py, px, sy, sx, ty, tx = choices[0]
    return color, cells, py, px, sy, sx, ty, tx


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = [(color, cells) for color, cells in _components(g) if color != bg]
    divider = _find_divider(g, comps)
    if divider is None:
        return g
    color, line, py, px, sy, sx, ty, tx = divider
    # The small object in the elbow's inner corner is the shape key.
    inside = []
    for obj_color, cells in comps:
        if cells & line:
            continue
        ok = True
        for y, x in cells:
            if (y - py) * sy < 0 or (x - px) * tx < 0:
                ok = False
                break
        # The two arms point along the row/column; the corner quadrant uses
        # those same signs on both axes.
        if ok:
            inside.append((obj_color, cells))
    if not inside:
        return g
    # Use the most substantial enclosed object, preferring the one nearest the elbow.
    inside.sort(key=lambda item: (len(item[1]), -min(abs(y-py)+abs(x-px) for y, x in item[1])), reverse=True)
    key_color, key_cells = inside[0]
    key_shape = _norm(key_cells)
    matches = []
    for obj_color, cells in comps:
        if cells == key_cells or cells & line:
            continue
        if _norm(cells) == key_shape:
            # A matching copy should be outside the key corner.
            if any((y-py) * sy < 0 or (x-px) * tx < 0 for y, x in cells):
                matches.append((obj_color, cells))
    if matches:
        # There is normally one duplicate. In case of several, prefer the one
        # with the same source color as the key, then the first in scan order.
        matches.sort(key=lambda item: (item[0] != key_color, min(y for y, x in item[1]), min(x for y, x in item[1])))
        for y, x in matches[0][1]:
            g[y][x] = color
    return g


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
