            color = grid[r][c]
            q, cells = [(r, c)], set()
            seen.add((r, c))
            while q:
                y, x = q.pop()
                cells.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx)); q.append((yy, xx))
            comps.append((color, cells))
    return comps


def _norm(cells):
    my, mx = min(y for y, x in cells), min(x for y, x in cells)
    return frozenset((y-my, x-mx) for y, x in cells)


def _line_component(comps):
    for color, cells in comps:
        # A straight, connected line acts as the mirror axis. Use long lines;
        # isolated background-colored cells do not count.
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        if len(cells) >= 4 and (len(set(ys)) == 1 or len(set(xs)) == 1):
            return color, cells, ("h" if len(set(ys)) == 1 else "v")
    return None


def transform(grid):
    g = [row[:] for row in grid]
    comps = _components(g)
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    # Identify long single-color straight divider(s). In these tasks a line
    # separates a repeated motif from a matching motif on the other side.
    lines = []
    for color, cells in comps:
        ys = [y for y, x in cells]; xs = [x for y, x in cells]
        if len(cells) >= 4 and (len(set(ys)) == 1 or len(set(xs)) == 1):
            lines.append((color, cells, "h" if len(set(ys)) == 1 else "v"))
    if not lines:
        return g
    # Largest straight component is the axis.
    color, line, orient = max(lines, key=lambda z: len(z[1]))
    axis = next(iter(line))[0 if orient == "h" else 1]
    objects = [(co, ce) for co, ce in comps if ce != line and co != bg]
    # Detect a repeated shape pair across the axis. One copy is the key/mask,
    # another is recolored with the divider color. Prefer objects whose mirror
    # counterpart has identical normalized shape.
    candidates = []
    for i, (co, ce) in enumerate(objects):
        lo = min(y for y, x in ce) if orient == "h" else min(x for y, x in ce)
        hi = max(y for y, x in ce) if orient == "h" else max(x for y, x in ce)
        side = -1 if (lo + hi) / 2 < axis else 1
        shape = _norm(ce)
        for j, (co2, ce2) in enumerate(objects):
            if i == j or _norm(ce2) != shape:
                continue
            lo2 = min(y for y, x in ce2) if orient == "h" else min(x for y, x in ce2)
            hi2 = max(y for y, x in ce2) if orient == "h" else max(x for y, x in ce2)
            side2 = -1 if (lo2 + hi2) / 2 < axis else 1
            if side == side2:
                continue
            # Recolor the copy on the opposite side from the reference object.
            candidates.append((len(ce), co, ce, co2, ce2))
    if candidates:
        _, _, source, target_color, target = max(candidates, key=lambda z: z[0])
        # Color the target occurrence to the axis color; demos show only one
        # duplicate object is changed, not all same-shaped decorations.
        for y, x in target:
            g[y][x] = color
    return g


