def components(grid):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for y in range(h):
        for x in range(w):
            if (y,x) in seen: continue
            col=grid[y][x]; q=[(y,x)]; seen.add((y,x)); cells=set()
            while q:
                a,b=q.pop(); cells.add((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    p,t=a+da,b+db
                    if 0<=p<h and 0<=t<w and (p,t) not in seen and grid[p][t]==col:
                        seen.add((p,t));q.append((p,t))
            out.append((col,cells))
    return out


def norm(cells):
    y0=min(y for y,x in cells); x0=min(x for y,x in cells)
    return frozenset((y-y0,x-x0) for y,x in cells)


def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    cs=components(g)
    # The long colored line is an instruction marker; its color is used for
    # recoloring the occurrence of a shape matching the nearby exemplar.
    lines=[]
    for color,cells in cs:
        ys={y for y,x in cells}; xs={x for y,x in cells}
        if len(cells)>=4 and (len(ys)==1 or len(xs)==1):
            lines.append((color,cells,'h' if len(ys)==1 else 'v'))
    if not lines: return g
    marker, line, orient=max(lines,key=lambda z:len(z[1]))
    axis=next(iter(line))[0 if orient=='h' else 1]
    # Find a non-background exemplar immediately adjacent to the marker.
    objs=[(col,cells) for col,cells in cs if cells!=line and col!=bg]
    exemplars=[]
    for col,cells in objs:
        # Minimum distance to the marker pixels (Manhattan adjacency).
        dist=min(abs(y-a)+abs(x-b) for y,x in cells for a,b in line)
        if dist<=2:
            exemplars.append((dist,-len(cells),col,cells))
    if not exemplars: return g
    _,_,_,ex=min(exemplars)
    shape=norm(ex)
    targets=[]
    for col,cells in objs:
        if cells==ex: continue
        if norm(cells)==shape:
            targets.append((col,cells))
    if not targets: return g
    # If multiple copies, recolor the one on the opposite side of the marker;
    # otherwise simply use the sole matching occurrence.
    def side(cells):
        vals=[y if orient=='h' else x for y,x in cells]
        return -1 if sum(vals)/len(vals)<axis else 1
    opposite=[item for item in targets if side(item[1]) != side(ex)]
    col,cells=(opposite or targets)[0]
    for y,x in cells: g[y][x]=marker
    return g

