 "content": "from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    bg=Counter(v for row in out for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for y in range(h):
        for x in range(w):
            if (y,x) in seen: continue
            color=out[y][x]; q=[(y,x)]; seen.add((y,x)); cells=set()
            while q:
                a,b=q.pop(); cells.add((a,b))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=a+dy,b+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and out[yy][xx]==color:
                        seen.add((yy,xx));q.append((yy,xx))
            comps.append((color,cells))
    # Locate the bent marker and its elbow/arm directions.
    marker_info=None
    for color,cells in comps:
        for ey,ex in cells:
            for dy,dx in ((-1,0),(1,0)):
                for vy,vx in ((0,-1),(0,1)):
                    a=b=1
                    while (ey+dy*a,ex+dx*a) in cells: a+=1
                    while (ey+vy*b,ex+vx*b) in cells: b+=1
                    if a<3 or b<3: continue
                    shape={(ey+dy*k,ex+dx*k) for k in range(a)}|{(ey+vy*k,ex+vx*k) for k in range(b)}
                    if shape==cells:
                        marker_info=(color,cells,ey,ex,dy,vx)
                        break
                if marker_info: break
            if marker_info: break
        if marker_info: break
    if marker_info is None: return out
    color,line,ey,ex,dy,vx=marker_info
    # The target is the largest complete object in the quadrant opposite the
    # two L arms.
    sy=1 if dy<0 else -1
    sx=1 if vx<0 else -1
    choices=[]
    for c,cells in comps:
        if c==bg or cells==line: continue
        if all((y-ey)*sy>0 and (x-ex)*sx>0 for y,x in cells):
            choices.append((len(cells),cells))
    if choices:
        _,target=max(choices,key=lambda z:z[0])
        for y,x in target: out[y][x]=color
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
