 "content": "from collections import Counter

def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(out),len(out[0])
    bg=Counter(v for row in out for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for y in range(h):
        for x in range(w):
            if (y,x) in seen: continue
            color=out[y][x]; q=[(y,x)]; seen.add((y,x)); cells=set()
            while q:
                a,b=q.pop(); cells.add((a,b))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=a+dy,b+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and out[yy][xx]==color:
                        seen.add((yy,xx));q.append((yy,xx))
            comps.append((color,cells))
    # The L-shaped 9 marker points into its open quadrant. Select the largest
    # non-background component wholly in that quadrant and recolor it 9.
    markers=[cells for col,cells in comps if col==9 and len(cells)>=5]
    if not markers: return out
    marker=max(markers,key=len)
    ey=max(y for y,x in marker); ex=min(x for y,x in marker)
    choices=[]
    for color,cells in comps:
        if color in (bg,9): continue
        if all(y<ey and x<ex for y,x in cells): choices.append((len(cells),cells))
    if choices:
        _,target=max(choices,key=lambda z:z[0])
        for y,x in target: out[y][x]=9
    return out

